<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/operations.php';require_once dirname(__DIR__).'/private/ui.php';
$id=(int)($_GET['id']??0);if($id<1){http_response_code(400);exit('Aufgabe ungültig.');}
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$v=opsVersion($_POST);if(($_POST['action']??'')==='note')opsTaskNote($pdo,(int)$_SESSION['admin_id'],$id,(string)($_POST['notes']??''),$v);elseif(($_POST['action']??'')==='assign')opsAssignTask($pdo,(int)$_SESSION['admin_id'],$id,(int)($_POST['worker_id']??0),$v);elseif(($_POST['action']??'')==='status')opsSetDone($pdo,(int)$_SESSION['admin_id'],$id,($_POST['done']??'')==='1',$v);else throw new RuntimeException('Aktion unbekannt.');if(($_POST['action']??'')==='status'){require_once dirname(__DIR__).'/private/planning_store.php';gszSuggestWeek($pdo,(int)$_SESSION['admin_id']);}$_SESSION['app_notice']='Änderung gespeichert.';}catch(Throwable $e){gszUiError($e);}redirect('task.php?id='.$id);}
try{opsRequire($pdo);$q=$pdo->prepare('SELECT t.*,p.name property_name,p.address FROM tasks t LEFT JOIN properties p ON p.id=t.property_id WHERE t.id=?');$q->execute([$id]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Aufgabe nicht gefunden.');}$workers=$pdo->query('SELECT id,name,active FROM operations_workers ORDER BY name,id LIMIT 200')->fetchAll();$history=opsHistory($pdo,'task',$id);}catch(Throwable $e){http_response_code(503);exit('Aufgabe nicht verfügbar. Migration/Betriebsstand prüfen.');}gszPageStart($t['title']);
?><p><?=e($t['property_name']??'Ohne Objekt')?> · <?=e($t['due_date']??'Ohne Datum')?> · <?=$t['done']?'Erledigt':'Offen'?></p><p><a href="planner.php?date=<?=e($t['due_date']?:date('Y-m-d'))?>">Im Tagesplan bearbeiten</a><?php if($t['property_id']):?> · <a href="property.php?id=<?=(int)$t['property_id']?>">Objektakte</a> · <a href="worklogs.php?property_id=<?=(int)$t['property_id']?>">Freiwilligen Arbeitsnachweis erfassen</a><?php endif?></p><p>Keine Pflichtfotos oder Pflichtnachweise. Erledigtstatus und optionale Notiz genügen.</p>
<section class="card"><form method="post"><?php gszFields('status');?><input type="hidden" name="row_version" value="<?=(int)$t['row_version']?>"><input type="hidden" name="done" value="<?=$t['done']?'0':'1'?>"><button><?=$t['done']?'Wieder öffnen':'✓ Erledigt'?></button></form><form method="post"><?php gszFields('note');?><input type="hidden" name="row_version" value="<?=(int)$t['row_version']?>"><label>Optionale Notiz<textarea name="notes" maxlength="5000"><?=e($t['notes'])?></textarea></label><button>Notiz speichern</button></form><form method="post"><?php gszFields('assign');?><input type="hidden" name="row_version" value="<?=(int)$t['row_version']?>"><label>Ausführung zuordnen<select name="worker_id"><option value="0">Inhaber / nicht gesondert zugeordnet</option><?php foreach($workers as $w):?><option value="<?=(int)$w['id']?>" <?=(int)$t['assigned_worker_id']===(int)$w['id']?'selected':''?> <?=!$w['active']?'disabled':''?>><?=e($w['name'])?><?=$w['active']?'':' (inaktiv)'?></option><?php endforeach?></select></label><button>Zuweisung speichern</button></form></section><section class="card"><h2>Änderungshistorie</h2><?php if($t['done']&&!$t['completed_at']):?><p>Historisch erledigt; Erledigungszeitpunkt unbekannt.</p><?php endif?><?php foreach($history as $h):?><details><summary><?=e($h['created_at'].' UTC · '.$h['action'])?></summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e($h['changes_json'])?></pre></details><?php endforeach?></section><?php gszPageEnd();?>
